function mineAt(x,y){if(x<0||y<0||x>=WORLD||y>=WORLD||isRemoved(x,y)||Math.hypot(x-state.x,y-state.y)>1.65)return;mining={x,y,progress:0,type:typeAt(x,y)};draw();const duration=Math.max(210,850/power());const interval=55;const start=performance.now();const tick=now=>{if(!mining||mining.x!==x||mining.y!==y)return;mining.progress=Math.min(1,(now-start)/duration);draw();if(mining.progress>=1)completeMine(x,y);else setTimeout(()=>requestAnimationFrame(tick),interval)};requestAnimationFrame(tick)}
function completeMine(x,y){const type=mining.type;mining=null;state.removed.push(y*WORLD+x);state.mined++;state.xp+=type==='rare'?24:type==='crystal'?14:8;let gain=Math.max(1,Math.floor((type==='rare'?8:type==='crystal'?3:1+Math.random()*2)*power()));state.bits+=gain;let msg=`+${gain} bits`;if(type==='rare'){let sat=Math.max(1,Math.floor((8+Math.random()*18)*luck()));state.sats+=sat;state.foundRare++;msg+=` · +${sat} sat points!`;addFeed('💎','<strong>You uncovered a sat block!</strong> +'+sat+' fictional sat points');}if(type==='crystal'&&Math.random()<.36*luck()||type==='rare'&&Math.random()<.75){state.boxes++;addFeed('📦','<strong>PixelPioneer</strong> found a loot box');msg+=' · loot box found!'}else addFeed('⛏️',`<strong>PixelPioneer</strong> mined ${type} · +${gain} bits`);toast(msg);save();draw()}
function move(dx,dy){if(Date.now()-lastMove<100)return;lastMove=Date.now();let nx=Math.max(1,Math.min(WORLD-2,state.x+dx)),ny=Math.max(1,Math.min(WORLD-2,state.y+dy));state.x=nx;state.y=ny;mining=null;save();draw()}
function addFeed(icon,text){let e=document.createElement('div');e.className='feedrow';e.innerHTML=`<span class="feedicon">${icon}</span><div>${text}<time>just now · Sector 07</time></div>`;$('#feed').prepend(e);while($('#feed').children.length>4)$('#feed').lastChild.remove()}
function renderUI(){const fmt=n=>n.toLocaleString();$('#topBalance').textContent=fmt(state.bits);$('#blocksFound').textContent=fmt(state.removed.length);$('#minedStat').textContent=fmt(state.mined);$('#bitsStat').innerHTML=fmt(state.bits)+'<span> bits</span>';$('#boxStat').innerHTML=state.boxes+'<span> ready</span>';$('#powerStat').innerHTML=power().toFixed(1)+'<span>×</span>';$('#coords').textContent=`X: ${String(state.x).padStart(2,'0')} · Y: ${String(state.y).padStart(2,'0')}`;let lv=level(),xp=state.xp%100;$('#levelText').textContent=lv;$('#xpText').textContent=`${xp} / 100 XP` $('#levelProgress').style.width=xp+'%';$('#rankTag').textContent=lv<3?'ROOKIE':lv<6?'SCOUT':'PROSPECTOR';let pct=Math.min(100,state.removed.length/400*100);$('#worldProgress').style.width=Math.max(2,pct)+'%';$('#zoneLabel').textContent=`ZONE ${1+Math.floor(state.removed.length/40)} · ${Math.floor(pct)}%`;$('#loadout').innerHTML=['power','luck','speed','luck'].map((type,slot)=>{let id=slot===3?null:state.equipped[type],it=id==null?null:items[id];return `<button class="gear-slot" data-gear="${type}"><span class="gear-icon">${it?.icon||({power:'⛏️',luck:'🍀',speed:'🥾'}[type])}</span><span class="gear-text"><small>${slot===3?'CHARM SLOT':type.toUpperCase()}</small><strong>${slot===3?'Empty slot':it?.name||'Basic gear'}</strong></span><span class="gear-boost">${it?'×'+it.boost.toFixed(2):''}</span></button>`}).join('');let costs=[20+state.upgrades*35,70+state.upgrades*80];$('#upgradeList').innerHTML=[['⛏️','Power core','Mining power +35%',costs[0]],['🍀','Lucky finder','Better loot odds',costs[1]]].map((u,i)=>`<div class="upgrade"><span class="upgrade-icon">${u[0]}</span><div class="upgrade-info"><strong>${u[1]} · Lv ${i===0?state.upgrades+1:Math.floor(state.upgrades/2)+1}</strong><small>${u[2]}</small></div><button class="buy" data-up="${i}" ${state.bits<u[3]?'disabled':''}>${u[3]} bits</button></div>`).join('');$('#boxArea').innerHTML=state.boxes?`<div class="box-card"><div class="box-icon">🎁</div><div class="box-info"><strong>Frontier supply crate</strong><small>One of 32 unique items inside</small></div><button class="openbox" id="openBox">OPEN · ${state.boxes}</button></div>`:'<div class="box-empty">Mine glowing blocks to find a loot box.</div>';$('#onlineCount').textContent=128+Math.floor(Math.sin(Date.now()/7000)*9);$('#inventoryBtn').onclick=openInventory;$('#gearBtn').onclick=openInventory;$('#loadout').querySelectorAll('[data-gear]').forEach(b=>b.onclick=openInventory);$('#upgradeList').querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>buyUpgrade(+b.dataset.up));const ob=$('#openBox');if(ob)ob.onclick=openBox;}
